// [MEDIUM_PRIORITY] UX_POLISH: Accessibility considered
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.facadeimport timber.log.Timberimport com.roshan.persona.connectivity.call.BouncerResultimport com.roshan.persona.connectivity.call.CallEngineimport com.roshan.persona.connectivity.call.CallResultimport com.roshan.persona.connectivity.call.IncomingCallActionimport com.roshan.persona.connectivity.call.SpamDetectorEngineimport com.roshan.persona.connectivity.contact.ContactManagerimport com.roshan.persona.connectivity.contact.ContactSearcherimport com.roshan.persona.connectivity.contact.SimManagerimport com.roshan.persona.connectivity.messaging.OutboundExecutorimport com.roshan.persona.connectivity.messaging.SendResultimport com.roshan.persona.connectivity.model.CallStateimport com.roshan.persona.connectivity.model.CommsEntryimport com.roshan.persona.connectivity.model.CommsInsightimport com.roshan.persona.connectivity.model.ContactInfoimport com.roshan.persona.connectivity.model.ContactMatchResultimport com.roshan.persona.connectivity.model.MessagingAppimport com.roshan.persona.connectivity.model.ShareContentimport com.roshan.persona.connectivity.model.ShareTargetimport com.roshan.persona.connectivity.model.SimInfoimport com.roshan.persona.connectivity.model.SimSlotimport com.roshan.persona.connectivity.model.SmartReplySuggestionimport com.roshan.persona.connectivity.model.SmsMessageimport com.roshan.persona.connectivity.model.SmsStatusimport com.roshan.persona.connectivity.model.SosStatusimport com.roshan.persona.connectivity.model.SosTriggerimport com.roshan.persona.connectivity.recording.CallRecordingimport com.roshan.persona.connectivity.recording.CallRecordingEngineimport com.roshan.persona.connectivity.sms.SmsEngineimport com.roshan.persona.connectivity.sms.SmsTemplateManagerimport com.roshan.persona.connectivity.sos.EmergencySOSEngineimport com.roshan.persona.connectivity.sos.ProactiveCommsEngineimport com.roshan.persona.connectivity.sos.ProactiveSuggestionimport com.roshan.persona.connectivity.unified.CommsHistoryEngineimport com.roshan.persona.connectivity.unified.LiveTranslationBridgeimport com.roshan.persona.connectivity.unified.MessagingUnificationEngineimport com.roshan.persona.connectivity.unified.ShareEngineimport com.roshan.persona.connectivity.unified.UnifiedMessageimport kotlinx.coroutines.flow.Flow/** * NOUS — Connectivity Facade (Module 11 v3 — Step 11.8, FINAL). * * Single entry point for ALL connectivity operations. Aggregates the 12 v3 * engines into one cohesive API that the Brain (via [com.roshan.persona.connectivity.skills.NousCallSkill] * and [com.roshan.persona.connectivity.skills.NousSendSmsSkill]) and the UI * (via ViewModel) consume. * * ## Why a Facade? * * Without a Facade, the Brain and UI would need to know about: *   - ContactSearcher + SimManager + CallEngine + SpamDetectorEngine *   - SmsEngine + SmartReplyEngine + SmsTemplateManager *   - OutboundExecutor + MessagingAccessibilityBridge *   - MessagingUnificationEngine + CommsHistoryEngine *   - ShareEngine + LiveTranslationBridge + TranslationService *   - CallRecordingEngine + Aes256Encryptor + TranscriptionLlm *   - EmergencySOSEngine + ProactiveCommsEngine * * That's 16+ classes. The Facade hides them behind **one** interface so * callers only need to learn `ConnectivityFacade`. * * ## Operations grouped by engine * * | Group              | Methods                                                         | * |--------------------|-----------------------------------------------------------------| * | Calls              | [callContact], [placeCall], [handleIncomingCall], [endCall]    | * | SMS                | [sendSms], [sendSmsToContact], [readUnreadSms], [getSmartReplies] | * | App messaging      | [sendAppMessage]                                                | * | Contacts           | [searchContacts], [addContact], [deleteContact]                 | * | SIM                | [getActiveSims], [setPreferredSim]                              | * | Unified inbox      | [incomingMessages], [getUnreadMessages], [markAppRead]          | * | Comms history      | [getUnifiedTimeline], [searchComms], [getCommsInsights]         | * | Share              | [getShareTargets], [shareContent]                               | * | Live translation   | [startLiveTranslation], [stopLiveTranslation]                   | * | Recording          | [startCallRecording], [stopCallRecording], [searchCallRecordings] | * | SOS                | [triggerSos], [cancelSos], [isSosActive]                        | * | Proactive          | [getProactiveSuggestions]                                       | * | Templates          | [addSmsTemplate], [getSmsTemplate]                              | * * ## Privacy (per strategy v3 §"Privacy & Security") * *  - All data stays on-device — no cloud sync. *  - Smart reply uses LOCAL LLM only (PiiScrubber strips phone/OTP/email). *  - Call recordings are AES-256 encrypted at rest. *  - WhatsApp/Telegram messages are ephemerally parsed via NotificationListener. *  - SOS location shared ONLY to user-selected emergency contacts. * * ## Performance Budgets (per strategy v3 §"Performance Budgets") * *  - Contact search: < 20ms (FTS4 indexed) *  - Place call / send SMS: < 200ms *  - Smart reply generation: < 1s (local LLM) *  - Spam DB lookup: < 50ms *  - SOS trigger to dispatch: 5s (mandatory countdown) *  - Active Bouncer pickup: < 500ms *  - Proactive comms check: < 500ms * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Architecture — ConnectivityFacade</a> */class ConnectivityFacade(    private val callEngine: CallEngine,    private val spamDetector: SpamDetectorEngine,    private val smsEngine: SmsEngine,    private val smsTemplateManager: SmsTemplateManager,    private val contactSearcher: ContactSearcher,    private val contactManager: ContactManager,    private val simManager: SimManager,    private val outboundExecutor: OutboundExecutor,    private val messagingUnificationEngine: MessagingUnificationEngine,    private val commsHistoryEngine: CommsHistoryEngine,    private val shareEngine: ShareEngine,    private val liveTranslationBridge: LiveTranslationBridge,    private val callRecordingEngine: CallRecordingEngine,    private val emergencySosEngine: EmergencySOSEngine,    private val proactiveCommsEngine: ProactiveCommsEngine,) {    // ═══════════════════════════════════════════════════════════════════════════    // 1. CALL OPERATIONS    // ═══════════════════════════════════════════════════════════════════════════    /**     * Call a contact by name (the "call mom" entry point).     *     * Flow:     *  1. Search contacts by [contactQuery] (fuzzy name match).     *  2. If no match → returns [CallResult.FAILED] with reason "Contact not found".     *  3. If match → check SIM preference via [SimManager].     *  4. Place the call via [CallEngine.placeCall].     *     * @param contactQuery the contact name (or phone number) to call.     * @param simSlot explicit SIM slot (null = auto from SimManager preference).     * @return the call result.     */    suspend fun callContact(contactQuery: String, simSlot: SimSlot? = null): CallResult {        Timber.tag(TAG).i("callContact: $contactQuery (sim=$simSlot)")        val contact = contactSearcher.findBestMatch(contactQuery)            ?: return CallResult.FAILED("Contact not found: $contactQuery")        val resolvedSlot = simSlot ?: simManager.getPreferredSim(contact.id)        return callEngine.placeCall(contact.primaryPhone, resolvedSlot?.slotIndex)    }    /**     * Place a call directly to a phone number (no contact lookup).     *     * @param phoneNumber the number to call.     * @param simSlot explicit SIM slot (null = default).     */    suspend fun placeCall(phoneNumber: String, simSlot: SimSlot? = null): CallResult {        return callEngine.placeCall(phoneNumber, simSlot?.slotIndex)    }    /**     * Handle an incoming call (called by CallStateMonitor when RINGING detected).     */    suspend fun handleIncomingCall(phoneNumber: String): IncomingCallAction {        return callEngine.handleIncomingCall(phoneNumber)    }    /** Activate the v3 Active Call Bouncer for an unknown caller. */    suspend fun activateCallBouncer(phoneNumber: String): BouncerResult {        return callEngine.activateBouncer(phoneNumber)    }    /** User accepted a bounced call. */    fun acceptBouncedCall() = callEngine.acceptBouncedCall()    /** User rejected a bounced call (or auto-reject telemarketer). */    suspend fun rejectBouncedCall() = callEngine.rejectBouncedCall()    /** Answer the current incoming call. */    suspend fun answerCall(): Boolean = callEngine.answerCall()    /** Reject the current incoming call. */    suspend fun rejectCall(): Boolean = callEngine.rejectCall()    /** End the current call. */    suspend fun endCall(): Boolean = callEngine.endCall()    /** Get the current call state. */    fun getCallState(): CallState = callEngine.getCurrentState()    /** Live call-state stream (RINGING / OFFHOOK / IDLE). */    fun callStateStream(): Flow<CallState> = callEngine.callState    // ═══════════════════════════════════════════════════════════════════════════    // 2. SMS OPERATIONS    // ═══════════════════════════════════════════════════════════════════════════    /**     * Send an SMS to a contact by name.     *     * Flow:     *  1. Search contacts by [contactQuery] (fuzzy match).     *  2. If no match → returns [SmsStatus.FAILED].     *  3. If match → send SMS via [SmsEngine.send].     *     * @param contactQuery the contact name.     * @param message the message body.     * @return the delivery status.     */    suspend fun sendSmsToContact(contactQuery: String, message: String): SmsStatus {        Timber.tag(TAG).i("sendSmsToContact: $contactQuery (msgLen=${message.length})")        val contact = contactSearcher.findBestMatch(contactQuery)            ?: return SmsStatus.FAILED        return smsEngine.send(contact.primaryPhone, message)    }    /**     * Send an SMS directly to a phone number.     */    suspend fun sendSms(phoneNumber: String, message: String): SmsStatus {        return smsEngine.send(phoneNumber, message)    }    /**     * Read all unread SMS aloud via TTS (Module 5 EmotionalTtsEngine).     *     * @return the messages that were read.     */    suspend fun readUnreadSms(): List<SmsMessage> {        return smsEngine.readUnreadAloud()    }    /**     * Get smart reply suggestions for an SMS message.     *     * Returns 3 contextual replies + Smart Payload (v3 elite) when device     * context is available (e.g., "Roshan is driving. ETA 15m").     *     * @param message the incoming SMS.     * @return smart reply suggestions.     */    suspend fun getSmartReplies(message: SmsMessage): SmartReplySuggestion {        return smsEngine.getSmartReplies(message)    }    /**     * Search SMS history by keyword.     */    suspend fun searchSmsHistory(query: String, limit: Int = 20): List<SmsMessage> {        return smsEngine.searchHistory(query, limit)    }    // ═══════════════════════════════════════════════════════════════════════════    // 3. APP MESSAGING (WHATSAPP / TELEGRAM / SIGNAL — v3 Elite)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Send a message via WhatsApp / Telegram / Signal.     *     * Flow (per strategy v3 §"Full-Spectrum Messaging Unification"):     *  1. Search contacts by [contactQuery].     *  2. If not found → returns [SendResult.FAILED].     *  3. Open the app's chat with the contact (Intent.ACTION_VIEW wa.me/...).     *  4. If accessibility service enabled → auto-click "Send" button.     *  5. If accessibility disabled → return MANUAL_CONFIRMATION_REQUIRED.     *     * @param app the messaging app (WHATSAPP / TELEGRAM / SIGNAL).     * @param contactQuery the contact name.     * @param message the message body.     * @return the send result.     */    suspend fun sendAppMessage(        app: MessagingApp,        contactQuery: String,        message: String,    ): SendResult {        Timber.tag(TAG).i("sendAppMessage: app=$app, contact=$contactQuery, msgLen=${message.length}")        val contact = contactSearcher.findBestMatch(contactQuery)            ?: return SendResult.FAILED("Contact not found: $contactQuery")        return outboundExecutor.send(app, contact.primaryPhone, message)    }    // ═══════════════════════════════════════════════════════════════════════════    // 4. CONTACT OPERATIONS    // ═══════════════════════════════════════════════════════════════════════════    /**     * Search contacts by name (fuzzy) or phone number.     *     * Performance: < 20ms (FTS4 indexed in real impl).     *     * @param query the search query ("mom", "rohit", "+919876").     * @return ranked list of matches (best first).     */    suspend fun searchContacts(query: String): List<ContactMatchResult> {        return contactSearcher.search(query)    }    /**     * Add a new contact.     */    suspend fun addContact(name: String, phoneNumber: String, email: String? = null): ContactInfo? {        return contactManager.addContact(name, phoneNumber, email)    }    /**     * Delete a contact by ID.     */    suspend fun deleteContact(contactId: String): Boolean {        return contactManager.deleteContact(contactId)    }    /**     * Set a contact's favorite status.     */    suspend fun setFavorite(contactId: String, isFavorite: Boolean): Boolean {        return contactManager.toggleFavorite(contactId, isFavorite)    }    /**     * Set a contact's trusted status (bypasses voice verification).     */    suspend fun setTrusted(contactId: String, isTrusted: Boolean): Boolean {        return contactManager.toggleTrusted(contactId, isTrusted)    }    // ═══════════════════════════════════════════════════════════════════════════    // 5. SIM OPERATIONS (India-First Dual-SIM Intelligence)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get all active SIMs on the device.     */    suspend fun getActiveSims(): List<SimInfo> {        return simManager.getActiveSims()    }    /**     * Set the preferred SIM for a contact (auto-learned or user-set).     */    fun setPreferredSim(contactId: String, slot: SimSlot, isAutoLearned: Boolean = false) {        simManager.setPreferredSim(contactId, slot, isAutoLearned)    }    /**     * Get the preferred SIM for a contact (null = default).     */    fun getPreferredSim(contactId: String): SimSlot? {        return simManager.getPreferredSim(contactId)    }    // ═══════════════════════════════════════════════════════════════════════════    // 6. UNIFIED INBOX (SMS + WhatsApp + Telegram + Signal)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Hot stream of incoming messages from ALL apps (NotificationListener).     *     * UI observes this to show unified inbox notifications.     */    fun incomingMessages(): Flow<UnifiedMessage> = messagingUnificationEngine.incomingMessages    /**     * Process an incoming notification (called by NotificationListenerService).     */    suspend fun processIncomingNotification(app: MessagingApp, sender: String, body: String) {        messagingUnificationEngine.processIncomingNotification(app, sender, body)    }    /**     * Get unread messages from all apps.     */    fun getUnreadMessages(): List<UnifiedMessage> = messagingUnificationEngine.getUnread()    /**     * Mark a message from [app] as read.     */    fun markAppRead(app: MessagingApp) = messagingUnificationEngine.markAsRead(app)    /**     * Get unread count per app.     */    fun getUnreadCounts(): Map<MessagingApp, Int> = messagingUnificationEngine.getUnreadCounts()    /**     * Check if NotificationListener is enabled.     */    fun isNotificationListenerEnabled(): Boolean = messagingUnificationEngine.isListenerEnabled()    // ═══════════════════════════════════════════════════════════════════════════    // 7. COMMS HISTORY (Unified Timeline + Search + Insights)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get the unified comms timeline (calls + SMS + WhatsApp + Telegram).     *     * @param sinceMs only entries after this timestamp (0 = all).     * @param limit max entries.     */    suspend fun getUnifiedTimeline(sinceMs: Long = 0, limit: Int = 100): List<CommsEntry> {        return commsHistoryEngine.getTimeline(sinceMs, limit)    }    /**     * Deep search across all comms ("show messages containing 'flight' from Mom").     */    suspend fun searchComms(query: String, limit: Int = 50): List<CommsEntry> {        return commsHistoryEngine.search(query, limit)    }    /**     * Get all comms for a contact (by phone number).     */    suspend fun getCommsForContact(phoneNumber: String, limit: Int = 50): List<CommsEntry> {        return commsHistoryEngine.getCommsForContact(phoneNumber, limit)    }    /**     * Generate comms insights ("You talk to Mom 5× more than Dad").     */    suspend fun getCommsInsights(): List<CommsInsight> {        return commsHistoryEngine.generateInsights()    }    // ═══════════════════════════════════════════════════════════════════════════    // 8. SHARE OPERATIONS (NOUS-enhanced)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get recommended share targets for [content] (WhatsApp for photos, SMS for short text).     */    suspend fun getShareTargets(content: ShareContent): List<ShareTarget> {        return shareEngine.getShareTargets(content)    }    /**     * Share [content] to [target].     *     * @return true if the share intent was launched.     */    suspend fun shareContent(content: ShareContent, target: ShareTarget): Boolean {        return shareEngine.share(content, target)    }    // ═══════════════════════════════════════════════════════════════════════════    // 9. LIVE TRANSLATION (v3 Elite — Real-Time Call Translation)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Start live call translation.     *     * Pipes active call audio to Module 5 STT → Module 4 LLM translation →     * display on screen.     *     * @param sourceLang the caller's language (e.g., "hi" for Hindi).     * @param targetLang the user's language (e.g., "en" for English).     * @return true if translation started.     */    fun startLiveTranslation(sourceLang: String, targetLang: String): Boolean {        liveTranslationBridge.start(sourceLang, targetLang)        return true    }    /**     * Process an audio chunk for live translation.     *     * Called by CallRecordingEngine or audio pipeline during an active call.     *     * @param audioChunk raw PCM audio.     */    suspend fun processAudioChunkForTranslation(audioChunk: ByteArray) {        liveTranslationBridge.processAudioChunk(audioChunk)    }    /**     * Stop live translation.     */    fun stopLiveTranslation() = liveTranslationBridge.stop()    /**     * Check if live translation is active.     */    fun isLiveTranslationActive(): Boolean = liveTranslationBridge.isLive()    // ═══════════════════════════════════════════════════════════════════════════    // 10. CALL RECORDING (AES-256 Encrypted, Accessibility Bypass)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Start recording the current call.     *     * @param contactName the other party's name.     * @param phoneNumber the other party's number.     * @return true if recording started.     */    fun startCallRecording(contactName: String, phoneNumber: String): Boolean {        return callRecordingEngine.startRecording(contactName, phoneNumber)    }    /**     * Stop recording and finalize (encrypt + transcribe async).     *     * @return the recording ID, or null if no recording was in progress.     */    suspend fun stopCallRecording(): String? {        return callRecordingEngine.stopRecording()    }    /**     * Search call recording transcripts ("What did Mom say about the trip?").     */    suspend fun searchCallRecordings(query: String, limit: Int = 10): List<CallRecording> {        return callRecordingEngine.searchTranscripts(query, limit)    }    /**     * Get recent call recordings.     */    suspend fun getRecentCallRecordings(limit: Int = 20): List<CallRecording> {        return callRecordingEngine.getRecentRecordings(limit)    }    /**     * Delete a call recording by ID.     */    suspend fun deleteCallRecording(recordingId: String): Boolean {        return callRecordingEngine.deleteRecording(recordingId)    }    /**     * Delete all call recordings (privacy: "Delete all recordings" in Settings).     */    suspend fun deleteAllCallRecordings(): Int {        return callRecordingEngine.deleteAllRecordings()    }    /**     * Check if currently recording a call.     */    fun isCallRecording(): Boolean = callRecordingEngine.isRecording()    // ═══════════════════════════════════════════════════════════════════════════    // 11. EMERGENCY SOS (5-Second Countdown, Failsafe)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Trigger the SOS sequence (5-second cancelable countdown → dispatch).     *     * @param trigger the SOS configuration (emergency contacts + options).     * @return the final status (CANCELLED or DISPATCHED).     */    suspend fun triggerSos(trigger: SosTrigger): SosStatus {        return emergencySosEngine.trigger(trigger)    }    /**     * Cancel the SOS countdown (user says "Cancel!" or taps screen).     */    fun cancelSos() = emergencySosEngine.cancel()    /**     * Check if SOS is currently active (countdown or dispatching).     */    fun isSosActive(): Boolean = emergencySosEngine.isActive()    /**     * Get the current SOS status.     */    fun sosStatus(): SosStatus = emergencySosEngine.status.value    // ═══════════════════════════════════════════════════════════════════════════    // 12. PROACTIVE COMMS (Predictive Suggestions Every 6 Hours)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Run a proactive comms check.     *     * Returns suggestions like:     *  - "Mom usually calls at 8 PM. Want me to call her now?"     *  - "Rohit is waiting for your reply (3 messages, 2h)."     *  - "Dad hasn't heard from you in 14 days."     *     * Called by WorkManager every 6 hours, or on-demand by the Brain.     */    suspend fun getProactiveSuggestions(): List<ProactiveSuggestion> {        return proactiveCommsEngine.check()    }    // ═══════════════════════════════════════════════════════════════════════════    // 13. SMS TEMPLATES (User-Defined Quick Replies)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Add a user-defined SMS template.     *     * "Send template 'meeting' to Rohit" → resolves to the template body.     */    fun addSmsTemplate(name: String, body: String) {        smsTemplateManager.setTemplate(name, body)    }    /**     * Get an SMS template by name.     */    fun getSmsTemplate(name: String): String? {        return smsTemplateManager.getTemplate(name)    }    /**     * List all SMS templates.     */    fun listSmsTemplates(): Map<String, String> {        return smsTemplateManager.getAllTemplates()    }    /**     * Remove an SMS template.     */    fun removeSmsTemplate(name: String): Boolean {        return smsTemplateManager.removeTemplate(name)    }    // ═══════════════════════════════════════════════════════════════════════════    // 14. SPAM DETECTION (Local DB + Pattern + ML Classifier)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Classify a phone number for spam risk.     *     * Returns SAFE (in contacts), LOW_RISK (unknown), HIGH_RISK (pattern match),     * or SPAM (in local blocklist).     */    suspend fun classifySpam(phoneNumber: String) = spamDetector.classify(phoneNumber)    /**     * Report a phone number as spam (user-initiated — "Mark this number as spam").     */    suspend fun reportSpam(phoneNumber: String, reason: String = "User-reported") {        spamDetector.reportSpam(phoneNumber, reason)    }    /**     * Remove a phone number from the spam database (false positive).     */    suspend fun unblockNumber(phoneNumber: String): Boolean {        return spamDetector.removeFromSpam(phoneNumber)    }    private companion object {        private const val TAG = "ConnectivityFacade"    }}